window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-d6b37d2a6f1e6899"]={"versions": [{"id": "FIG-d6b37d2a6f1e6899", "releases": ["R2.1.20", "R3.0.7"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> Organigramm / Rollen- und Governance-Modell der Qualitätssicherungs- und Konformitätsinfrastruktur (nicht-funktionales Architekturdiagramm).\n</li><li><strong>Technischer Zweck:</strong> Definition der institutionellen Zuständigkeiten und hierarchischen Autorisierungsbeziehungen für die formelle AUTOSAR-Konformitätsprüfung (Conformance Testing) gemäß Spezifikation <code>AUTOSAR_DS_Accreditation</code> (Releases R2.1.20, R3.0.7).\n</li><li><strong>Funktionale Einordnung:</strong> Etabliert die Vertrauenskette für die Vergabe von AUTOSAR-Konformitätszertifikaten. Es trennt die normative Überwachungs- und Begutachtungsinstanz von den operativen Prüfstellen, die Basis-Software-Module (BSW), RTE-Implementierungen oder Gesamtsysteme gegen die AUTOSAR-Spezifikationen validieren.\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Accreditation body (Assessors):</strong>\n<ul class=\"fig-list\"><li><em>Rolle:</em> Übergeordnete Akkreditierungsstelle bzw. Begutachtergremium (AUTOSAR-Gremien oder beauftragte unabhängige Auditoren).\n</li><li><em>Aufgabe:</em> Evaluierung, Autorisierung und kontinuierliche Überwachung der operativen Teststellen hinsichtlich Methodenkompetenz, Tooling und Testabdeckung.\n</li></ul>\n</li><li><strong>Third party Conformance Test Agency:</strong>\n<ul class=\"fig-list\"><li><em>Rolle:</em> Unabhängiges, externes Testlabor (Drittpartei).\n</li><li><em>Aufgabe:</em> Neutrale Durchführung von Konformitätstests für Tier-1-Zulieferer, Halbleiterhersteller oder OEMs ohne eigene Testakkreditierung.\n</li></ul>\n</li><li><strong>First party Conformance Test Agency (Product Supplier):</strong>\n<ul class=\"fig-list\"><li><em>Rolle:</em> Herstellerinterne Prüfstelle beim Produktlieferanten (z. B. BSW-Stack-Vendor oder Tier-1).\n</li><li><em>Aufgabe:</em> Durchführung akkreditierter Konformitätstests im eigenen Haus unter Beibehaltung nachgewiesener organisatorischer Unabhängigkeit und definierter Qualitätssicherungsprozesse.\n</li></ul>\n</li><li><strong>Beziehung (<code>Performs accreditation</code>):</strong>\n<ul class=\"fig-list\"><li>Gerichtete 1:n-Beziehung vom <em>Accreditation body</em> zu beiden <em>Conformance Test Agency</em>-Typen.\n</li><li>Keine BSW-Laufzeitschnittstelle, sondern ein formaler Audit-, Validierungs- und Autorisierungsvertrag (Konformität der Testsuites, Reproduzierbarkeit der Testausführung, Qualifikation der Testumgebung).\n</li></ul>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Da es sich um ein Governance-Strukturmodell handelt, liegt kein Laufzeitverhalten auf Bus- oder Task-Ebene vor. Der zugrundeliegende formale Prozess gliedert sich in folgende Phasen:</p>\n<ol class=\"fig-list\"><li><strong>Akkreditierungsantrag:</strong> Einreichung von Testwerkzeugen, Testumgebung (Test Harness), Testfällen und Qualitätsmanagement durch die Testagentur (First oder Third Party).\n</li><li><strong>Begutachtung (Assessment):</strong> Prüfung der Übereinstimmung der Testinfrastruktur mit den offiziellen <em>AUTOSAR Conformance Test Suites</em> und Auswertungsverfahren durch die Assessoren des <em>Accreditation body</em>.\n</li><li><strong>Erteilung der Akkreditierung:</strong> Autorisierung der Agentur zur Ausstellung offizieller Konformitätsprüfberichte (<em>Conformance Test Reports</em>).\n</li><li><strong>Operativer Prüfpfad (SUT-Prüfung):</strong>\n<ul class=\"fig-list\"><li>Übergabe des Prüflings (System Under Test, SUT – z. B. BSW-Treiber, Kommunikations-Stack, OS).\n</li><li>Ausführung der normativen Testsequenzen (Stimulus/Response, Boundary Values, Fehlereinprägung für Det/Dem).\n</li><li>Generierung des standardisierten Prüfprotokolls zur Vorlage beim OEM bzw. Konsortium.\n</li></ul>\n</li></ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Zulieferer &amp; BSW-Stack-Entwickler:</strong>\n<ul class=\"fig-list\"><li>Eigene Entwicklungs- und Testabteilungen dürfen offizielle AUTOSAR-Konformitätsnachweise nur dann ausstellen, wenn sie formal als <em>First party Conformance Test Agency</em> akkreditiert sind. Fehlt dieser Status, muss zwingend eine externe <em>Third party Conformance Test Agency</em> beauftragt werden.\n</li></ul>\n</li><li><strong>Treiber- und Modul-Design (MCAL / BSW):</strong>\n<ul class=\"fig-list\"><li>Entwickelte BSW-Module müssen strikt gegen die standardisierten SWS-Definitionen entworfen werden. Nicht-spezifikationskonforme API-Signaturen, abweichendes Reentrancy-Verhalten, unvollständige Rückgabewerte (z. B. <code>E_NOT_OK</code>) oder proprietäre Header-Abhängigkeiten führen bei der automatisierten Ausführung durch eine Test Agency zum unmittelbaren Scheitern des Konformitätstests.\n</li></ul>\n</li><li><strong>Testbarkeit &amp; Schnittstellen (Test Harness):</strong>\n<ul class=\"fig-list\"><li>Für Konformitätsmessungen müssen Module deterministische Schnittstellen für den Test-Harness bereitstellen (z. B. Abfangmechanismen für Callbacks, Upper-Tester-/Lower-Tester-Schnittstellen, Abfrage von PDU-Zählern und Interaktion mit dem Error-Hook-Mechanismus).\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-f9a7f4f004a9416a", "releases": ["R3.1.5", "R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> Organigramm / Rollen- und Governance-Modell der Qualitätssicherungs- und Konformitätsinfrastruktur (nicht-funktionales Architekturdiagramm).\n</li><li><strong>Technischer Zweck:</strong> Definition der institutionellen Zuständigkeiten und hierarchischen Autorisierungsbeziehungen für die formelle AUTOSAR-Konformitätsprüfung (Conformance Testing) gemäß Spezifikation <code>AUTOSAR_DS_Accreditation</code> (Releases R2.1.20, R3.0.7).\n</li><li><strong>Funktionale Einordnung:</strong> Etabliert die Vertrauenskette für die Vergabe von AUTOSAR-Konformitätszertifikaten. Es trennt die normative Überwachungs- und Begutachtungsinstanz von den operativen Prüfstellen, die Basis-Software-Module (BSW), RTE-Implementierungen oder Gesamtsysteme gegen die AUTOSAR-Spezifikationen validieren.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Accreditation body (Assessors):</strong>\n<ul class=\"fig-list\"><li><em>Rolle:</em> Übergeordnete Akkreditierungsstelle bzw. Begutachtergremium (AUTOSAR-Gremien oder beauftragte unabhängige Auditoren).\n</li><li><em>Aufgabe:</em> Evaluierung, Autorisierung und kontinuierliche Überwachung der operativen Teststellen hinsichtlich Methodenkompetenz, Tooling und Testabdeckung.\n</li></ul>\n</li><li><strong>Third party Conformance Test Agency:</strong>\n<ul class=\"fig-list\"><li><em>Rolle:</em> Unabhängiges, externes Testlabor (Drittpartei).\n</li><li><em>Aufgabe:</em> Neutrale Durchführung von Konformitätstests für Tier-1-Zulieferer, Halbleiterhersteller oder OEMs ohne eigene Testakkreditierung.\n</li></ul>\n</li><li><strong>First party Conformance Test Agency (Product Supplier):</strong>\n<ul class=\"fig-list\"><li><em>Rolle:</em> Herstellerinterne Prüfstelle beim Produktlieferanten (z. B. BSW-Stack-Vendor oder Tier-1).\n</li><li><em>Aufgabe:</em> Durchführung akkreditierter Konformitätstests im eigenen Haus unter Beibehaltung nachgewiesener organisatorischer Unabhängigkeit und definierter Qualitätssicherungsprozesse.\n</li></ul>\n</li><li><strong>Beziehung (<code>Performs accreditation</code>):</strong>\n<ul class=\"fig-list\"><li>Gerichtete 1:n-Beziehung vom <em>Accreditation body</em> zu beiden <em>Conformance Test Agency</em>-Typen.\n</li><li>Keine BSW-Laufzeitschnittstelle, sondern ein formaler Audit-, Validierungs- und Autorisierungsvertrag (Konformität der Testsuites, Reproduzierbarkeit der Testausführung, Qualifikation der Testumgebung).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Da es sich um ein Governance-Strukturmodell handelt, liegt kein Laufzeitverhalten auf Bus- oder Task-Ebene vor. Der zugrundeliegende formale Prozess gliedert sich in folgende Phasen:</p>\n<ol class=\"fig-list\"><li><strong>Akkreditierungsantrag:</strong> Einreichung von Testwerkzeugen, Testumgebung (Test Harness), Testfällen und Qualitätsmanagement durch die Testagentur (First oder Third Party).\n</li><li><strong>Begutachtung (Assessment):</strong> Prüfung der Übereinstimmung der Testinfrastruktur mit den offiziellen <em>AUTOSAR Conformance Test Suites</em> und Auswertungsverfahren durch die Assessoren des <em>Accreditation body</em>.\n</li><li><strong>Erteilung der Akkreditierung:</strong> Autorisierung der Agentur zur Ausstellung offizieller Konformitätsprüfberichte (<em>Conformance Test Reports</em>).\n</li><li><strong>Operativer Prüfpfad (SUT-Prüfung):</strong>\n<ul class=\"fig-list\"><li>Übergabe des Prüflings (System Under Test, SUT – z. B. BSW-Treiber, Kommunikations-Stack, OS).\n</li><li>Ausführung der normativen Testsequenzen (Stimulus/Response, Boundary Values, Fehlereinprägung für Det/Dem).\n</li><li>Generierung des standardisierten Prüfprotokolls zur Vorlage beim OEM bzw. Konsortium.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Zulieferer &amp; BSW-Stack-Entwickler:</strong>\n<ul class=\"fig-list\"><li>Eigene Entwicklungs- und Testabteilungen dürfen offizielle AUTOSAR-Konformitätsnachweise nur dann ausstellen, wenn sie formal als <em>First party Conformance Test Agency</em> akkreditiert sind. Fehlt dieser Status, muss zwingend eine externe <em>Third party Conformance Test Agency</em> beauftragt werden.\n</li></ul>\n</li><li><strong>Treiber- und Modul-Design (MCAL / BSW):</strong>\n<ul class=\"fig-list\"><li>Entwickelte BSW-Module müssen strikt gegen die standardisierten SWS-Definitionen entworfen werden. Nicht-spezifikationskonforme API-Signaturen, abweichendes Reentrancy-Verhalten, unvollständige Rückgabewerte (z. B. <code>E_NOT_OK</code>) oder proprietäre Header-Abhängigkeiten führen bei der automatisierten Ausführung durch eine Test Agency zum unmittelbaren Scheitern des Konformitätstests.\n</li></ul>\n</li><li><strong>Testbarkeit &amp; Schnittstellen (Test Harness):</strong>\n<ul class=\"fig-list\"><li>Für Konformitätsmessungen müssen Module deterministische Schnittstellen für den Test-Harness bereitstellen (z. B. Abfangmechanismen für Callbacks, Upper-Tester-/Lower-Tester-Schnittstellen, Abfrage von PDU-Zählern und Interaktion mit dem Error-Hook-Mechanismus).\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-d6b37d2a6f1e6899", "to": "FIG-f9a7f4f004a9416a", "fr": "R3.0.7", "tr": "R3.1.5", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
